package com.nth.desktop3d;

import android.app.*;import android.content.pm.ActivityInfo;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicReference;

/** Viewport-fitted sorted folders, stable resize/rotation, manual grid control and blank dock spaces. */
public final class AutoSort084Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;private SettingsModel model;private LauncherStore store;
    public AutoSort084Smoke(Instrumentation t,MainActivity a,String o){test=t;activity=a;output=o;}
    public MainActivity run()throws Exception {
        AtomicReference<SettingsModel> m=new AtomicReference<>();main(()->m.set((SettingsModel)call("settingsModel",new Class[]{})));model=m.get();store=model.store;JSONObject before=DesktopBackup.capture(activity,model);
        try{
            main(()->{call("closePanel",new Class[]{});store.page=0;store.mode=3;store.pages.get(0).clear();for(int n=0;n<20;n++){LauncherStore.Item folder=new LauncherStore.Item("folder",FolderRules.NAMES[n]);folder.cellX=FolderRules.X[n];folder.cellY=FolderRules.Y[n];folder.children.add(new LauncherStore.Item("builtin:notes","Notes"));store.pages.get(0).add(folder);}store.preferences.edit().putBoolean(AutoGrid.key("enabled",0),false).putBoolean("folder_pattern_page_0",true).putInt("desktop_padding",0).putInt("dock_space_count",5).putInt("dock_space_height",96).putBoolean("show_dock",false).putBoolean("dock_content",true).putInt("icon_size",70).apply();model.set("reduced_motion",1);store.save();call("applySettings",new Class[]{boolean.class},true);});idle(450);
            check(AutoGrid.active(store,0),"Original generated folders were not migrated to a fitted grid");assertFits();Map<String,PointF> small=centers();main(()->model.set("icon_size",130));idle(350);sameCenters(small,centers());assertFits();int[][] canonical=positions();capture("084-legacy-sort-fitted-above-dock");
            rotate(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);assertFits();check(model.value("grid_columns")>=8,"Landscape sorted grid wasted its horizontal space");rotate(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);assertFits();check(Arrays.deepEquals(canonical,positions()),"Rotation rewrote canonical folder positions");sameCenters(small,centers());
            main(()->model.set("grid_row_dp",144));idle(300);check(!AutoGrid.active(store,0)&&!store.preferences.getBoolean("folder_pattern_page_0",true),"Manual row height is still overridden by the sorted pattern");check((Integer)member(desktop(),"ch")==Ui.dp(activity,144)&&model.value("grid_row_dp")==144,"Grid setting and actual row height disagree");main(()->model.set("grid_row_dp",88));idle(300);check((Integer)member(desktop(),"ch")==Ui.dp(activity,88),"Manual grid slider did not change real spacing");
            int firstCount=store.pageCount();invoke("showAutoSort",new Class[]{});capture("084-fitted-sort-preview");click("Create sorted desktop");await(()->store.pageCount()>firstCount,"Auto-sort did not add a desktop");idle(400);check(store.pageCount()==firstCount+1&&store.pages.get(store.page).size()==20&&AutoGrid.active(store,store.page),"Portrait auto-sort did not allocate a fitted page");assertFits();
            rotate(ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE);main(()->{model.set("show_dock",1);model.set("dock_space_height",96);});idle(350);int count=store.pageCount();invoke("showAutoSort",new Class[]{});click("Create sorted desktop");idle(400);check(store.pageCount()>count+1,"Constrained sort did not allocate overflow desktops");int total=0;for(int page=count;page<store.pageCount();page++){final int target=page;main(()->{store.page=target;desktop().rebuild();});idle(250);total+=store.pages.get(page).size();assertFits();}check(total==20,"Overflow allocation lost or duplicated folders");main(()->{FolderSorter.undo(store);desktop().rebuild();});idle(300);check(store.pageCount()==count,"Undo left generated overflow desktops");
            // A blank is a deliberate spacer, independent of the default plus placeholder.
            invoke("putDockItem",new Class[]{int.class,LauncherStore.Item.class},0,new LauncherStore.Item("builtin:notes","Dock note"));invoke("showDockSpace",new Class[]{int.class},0);click("Leave empty");invoke("closePanel",new Class[]{});assertBlank();
            main(()->{View blank=((ViewGroup)((ViewGroup)field("dockContents")).getChildAt(0)).getChildAt(0);check(!(blank instanceof Button)&&blank.getBackground()==null,"Blank dock space still draws a plus card");});holdBlank();check(find("Leave empty")!=null,"Blank dock space cannot be edited by holding it");capture("084-leave-empty-dock-space");invoke("closePanel",new Class[]{});
            // Pending widget restore work for the cleared destination must also be removed.
            main(()->{store.dock.widget(1,-1,"com.nth.desktop3d.widgetfixture/.FixtureWidgetProvider",0,"Pending");store.preferences.edit().putString("restore_widgets","[{\"location\":\"dock\",\"slot\":1}]").apply();});invoke("showDockSpace",new Class[]{int.class},1);click("Leave empty");check(store.dock.slots.get(1).blank&&!store.dock.slots.get(1).widget()&&new JSONArray(store.preferences.getString("restore_widgets","[]")).length()==0,"Leave empty kept pending widget content");invoke("closePanel",new Class[]{});
            JSONObject archive=DesktopBackup.capture(activity,model);int autoPage=-1;for(int p=0;p<store.pageCount();p++)if(AutoGrid.active(store,p)){autoPage=p;break;}check(autoPage>=0,"Fitted pages disappeared before backup");final int saved=autoPage;main(()->{store.movePage(saved,0);desktop().rebuild();});idle(250);check(AutoGrid.active(store,0),"Desktop reorder lost its fitted-grid metadata");
            main(()->{try{model.importDesktopBackup(activity,new DesktopBackup.Prepared(archive,model));}catch(Exception e){throw new AssertionError(e);}});idle(350);assertBlank();check(AutoGrid.active(store,saved),"Backup lost fitted-grid metadata");LauncherStore reloaded=new LauncherStore(activity);check(reloaded.dock.slots.get(0).blank&&AutoGrid.active(reloaded,saved),"Reload lost the blank dock or fitted grid");JSONObject invalid=new JSONObject(archive.toString());invalid.getJSONArray("dock").getJSONObject(0).put("empty","yes");boolean rejected=false;try{new DesktopBackup.Prepared(invalid,model);}catch(JSONException expected){rejected=true;}check(rejected,"Backup accepted invalid empty-space state");
        }finally{rotate(ActivityInfo.SCREEN_ORIENTATION_PORTRAIT);main(()->{try{call("closePanel",new Class[]{});model.importDesktopBackup(activity,new DesktopBackup.Prepared(before,model));}catch(Exception e){throw new AssertionError(e);}});}
        return activity;
    }
    private void assertFits(){main(()->{Rect viewport=new Rect();desktop().getGlobalVisibleRect(viewport);for(View tile:tiles().values())if(tile instanceof IconTile){for(View part:new View[]{((IconTile)tile).getChildAt(0),((IconTile)tile).label})if(part.getVisibility()==View.VISIBLE){int[] p=new int[2];part.getLocationOnScreen(p);check(p[0]>=viewport.left-1&&p[1]>=viewport.top-1&&p[0]+part.getWidth()<=viewport.right+1&&p[1]+part.getHeight()<=viewport.bottom+1,"Sorted icon/label is outside usable desktop: "+tile.getContentDescription());}}ScrollView scroll=(ScrollView)member(desktop(),"scroller");check(!scroll.canScrollVertically(1)&&!scroll.canScrollVertically(-1),"A fitted page still scrolls out of position");check((Integer)member(desktop(),"columns")==model.value("grid_columns"),"Grid controls disagree with rendered columns");});}
    private void assertBlank(){check(store.dock.slots.get(0).blank&&store.dock.slots.get(0).item==null&&!store.dock.slots.get(0).widget(),"Leave empty did not clear content and keep a spacer");main(()->check(((ViewGroup)field("dockContents")).getChildCount()==5,"Leave empty removed a dock position"));}
    private void holdBlank(){AtomicReference<int[]> point=new AtomicReference<>();main(()->{View v=((ViewGroup)field("dockContents")).getChildAt(0);int[] p=new int[2];v.getLocationOnScreen(p);point.set(new int[]{p[0]+v.getWidth()/2,p[1]+v.getHeight()/2});});long now=SystemClock.uptimeMillis();pointer(now,0,point.get());idle(ViewConfiguration.getLongPressTimeout()+150);pointer(now,1,point.get());idle(250);}
    private void pointer(long start,int action,int[] p){MotionEvent event=MotionEvent.obtain(start,SystemClock.uptimeMillis(),action,p[0],p[1],0);event.setSource(InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(event,true);event.recycle();}
    private int[][] positions(){int[][] p=new int[store.pages.get(store.page).size()][2];for(int n=0;n<p.length;n++){p[n][0]=store.pages.get(store.page).get(n).cellX;p[n][1]=store.pages.get(store.page).get(n).cellY;}return p;}
    private Map<String,PointF> centers(){AtomicReference<Map<String,PointF>> result=new AtomicReference<>();main(()->{Map<String,PointF> points=new LinkedHashMap<>();for(Map.Entry<String,View> e:tiles().entrySet()){View icon=((IconTile)e.getValue()).getChildAt(0);int[] p=new int[2];icon.getLocationOnScreen(p);points.put(e.getKey(),new PointF(p[0]+icon.getWidth()/2f,p[1]+icon.getHeight()/2f));}result.set(points);});return result.get();}
    private void sameCenters(Map<String,PointF> before,Map<String,PointF> after){for(String id:before.keySet()){PointF a=before.get(id),b=after.get(id);check(b!=null&&Math.abs(a.x-b.x)<=2&&Math.abs(a.y-b.y)<=2,"Resizing or round-trip rotation shifted a folder");}}
    @SuppressWarnings("unchecked") private Map<String,View> tiles(){return (Map<String,View>)member(desktop(),"cellViews");}
    private DesktopView desktop(){return (DesktopView)field("desktop");}
    private Object member(Object object,String name){try{java.lang.reflect.Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}catch(Exception e){throw new AssertionError(e);}}
    private Object field(String name){return member(activity,name);}
    private Object call(String name,Class<?>[] types,Object...args){try{java.lang.reflect.Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private void invoke(String name,Class<?>[] types,Object...args){main(()->call(name,types,args));idle(250);}
    private void click(String text){main(()->{View v=find(text);check(v!=null,"Missing control "+text);v.performClick();});idle(250);}
    private View find(String text){return find(activity.getWindow().getDecorView(),text);}
    private View find(View v,String text){if(text.contentEquals(v.getContentDescription()==null?"":v.getContentDescription())||v instanceof TextView&&text.contentEquals(((TextView)v).getText()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=find(((ViewGroup)v).getChildAt(i),text);if(f!=null)return f;}return null;}
    private void rotate(int orientation){main(()->activity.setRequestedOrientation(orientation));await(()->activity.getResources().getConfiguration().orientation==(orientation==ActivityInfo.SCREEN_ORIENTATION_PORTRAIT?Configuration.ORIENTATION_PORTRAIT:Configuration.ORIENTATION_LANDSCAPE),"Rotation did not settle");idle(500);}
    private void main(Runnable action){AtomicReference<Throwable> error=new AtomicReference<>();test.runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError(error.get());}
    private void idle(long ms){SystemClock.sleep(ms);test.runOnMainSync(()->{});}
    private void await(java.util.function.BooleanSupplier done,String message){long until=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<until){if(done.getAsBoolean())return;idle(100);}throw new AssertionError(message);}
    private void capture(String name){idle(200);Bitmap image=test.getUiAutomation().takeScreenshot();File dir=output==null?new File(activity.getExternalFilesDir(null),"verification"):new File(output);dir.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(dir,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{image.recycle();}}
    private static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
}
